use anyhow::Result;
use risc0_zkvm::{default_prover, ExecutorEnv, Receipt};
use symthaea_zkproof_core::{EvolutionInput, EvolutionOutput};

// This is generated by the risc0-build crate in methods/
// For this prototype, we'll assume the ELF is available.
// In a real build, we'd use: include_bytes!(env!("SYMTHAEA_GUEST_ELF"))
pub const EVOLUTION_GUEST_ELF: &[u8] = &[]; 

pub struct EvolutionaryProver;

impl EvolutionaryProver {
    pub fn prove(input: EvolutionInput) -> Result<Receipt> {
        let env = ExecutorEnv::builder()
            .write(&input)?
            .build()?;

        let prover = default_prover();
        let receipt = prover.prove(env, EVOLUTION_GUEST_ELF)?;
        Ok(receipt)
    }

    pub fn verify(receipt: &Receipt) -> Result<EvolutionOutput> {
        receipt.verify(EVOLUTION_GUEST_ID)?; // GUEST_ID would be exported from methods/
        let output: EvolutionOutput = receipt.journal.decode()?;
        Ok(output)
    }
}
pub const EVOLUTION_GUEST_ID: [u32; 8] = [0; 8]; // Placeholder
